/**
 * @name Insecure JWT validation in oauthlib
 * @description JWT tokens decoded without proper signature verification
 * @kind path-problem
 * @problem.severity error
 * @id py/insecure-jwt-validation
 * @tags security
 *        external/cwe/cwe-345
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module JwtConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // JWT decode calls without verification
    exists(API::CallNode call |
      call = API::moduleImport("jwt").getMember(["decode"]).getACall() and
      sink = call
    )
  }
}

module JwtFlow = TaintTracking::Global<JwtConfig>;
import JwtFlow::PathGraph

from JwtFlow::PathNode source, JwtFlow::PathNode sink
where JwtFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "JWT decode with untrusted data from $@.", source.getNode(), "user input"
